import {emptyLearning} from './training-engine.js';
export function migrateLearning(s){if(s?.version===1){const out=structuredClone(s);out.version=2;out.learning=emptyLearning();return out}return s}
export function validateLearning(s){const l=s.learning;if(!l||l.version!==1||!Array.isArray(l.dayCompleted)||l.dayCompleted.length>12||l.dayCompleted.some(x=>!/^dt-(0[1-9]|1[0-2])$/.test(x))||new Set(l.dayCompleted).size!==l.dayCompleted.length||!l.dayProgress||typeof l.dayProgress!=='object'||Array.isArray(l.dayProgress)||!Array.isArray(l.attempts)||l.attempts.length>100000)throw Error('Invalid learning progress');for(const [id,p] of Object.entries(l.dayProgress)){if(!/^dt-(0[1-9]|1[0-2])$/.test(id)||!p||typeof p.exerciseCorrect!=='boolean'||p.exerciseAnswer!==undefined&&(typeof p.exerciseAnswer!=='number'||!Number.isFinite(p.exerciseAnswer))||!p.checkAnswers||typeof p.checkAnswers!=='object'||Object.values(p.checkAnswers).some(v=>typeof v!=='string'))throw Error('Invalid lesson progress')}const ids=new Set();for(const a of l.attempts){if(!a||typeof a.id!=='string'||ids.has(a.id)||typeof a.questionId!=='string'||typeof a.sessionId!=='string'||typeof a.correct!=='boolean'||typeof a.hinted!=='boolean'||a.revealed!==undefined&&typeof a.revealed!=='boolean'||!['string','number'].includes(typeof a.answer)||typeof a.answer==='number'&&!Number.isFinite(a.answer)||!Number.isFinite(Date.parse(a.at)))throw Error('Invalid challenge attempt');ids.add(a.id)}if(l.session){const t=l.session;if(typeof t.id!=='string'||!['quick','topic','mixed','review'].includes(t.mode)||!Number.isInteger(t.seed)||!Array.isArray(t.ids)||t.ids.length>20||t.ids.some(id=>typeof id!=='string')||new Set(t.ids).size!==t.ids.length||!Number.isInteger(t.index)||t.index<0||t.index>t.ids.length||typeof t.submitted!=='boolean'||!t.answers||typeof t.answers!=='object'||Array.isArray(t.answers)||!t.hinted||typeof t.hinted!=='object'||Array.isArray(t.hinted)||Object.values(t.hinted).some(v=>typeof v!=='boolean'))throw Error('Invalid challenge session');for(const [id,a] of Object.entries(t.answers))if(!t.ids.includes(id)||!a||a.id!==t.id+':'+id||!ids.has(a.id))throw Error('Invalid session answer');for(let i=0;i<t.index;i++)if(!t.answers[t.ids[i]])throw Error('Missing earlier session answer');if(t.submitted&&t.ids.some(id=>!t.answers[id]))throw Error('Incomplete submitted quiz')}return s}
